#include <algorithm>
#include <cassert>
#include <bit>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <map>
#include <numeric>
#include <string>
#include <vector>
namespace {
std::size_t checks=0;
void require(bool v){++checks;if(!v)std::abort();}
int mu(std::size_t n){int sign=1;for(std::size_t p=2;p<=n/p;++p)if(n%p==0){n/=p;sign=-sign;if(n%p==0)return 0;}return n>1?-sign:sign;}
void integer_suite(){
 IntegerSieve sieve(256);for(int n=0;n<=256;++n){bool prime=n>=2;int least=0;for(int d=2;d<=n;++d)if(n%d==0){least=d;break;}for(int d=2;d<=n/d;++d)if(n%d==0)prime=false;require(sieve.is_prime(n)==prime);require(is_prime(n)==prime);require(sieve.least_prime_factor[n]==least);}
 for(std::size_t n:{0U,1U,2U,3U,8U,31U,32U,33U,127U}){
  std::vector<std::int64_t>a(n),b(n);for(std::size_t i=0;i<n;++i){a[i]=static_cast<int>(i%7)-3;b[i]=static_cast<int>(i%5)-2;}
  for(bool multiple:{false,true})for(bool inverse:{false,true}){
   auto expected=a,actual=a;for(std::size_t i=1;i<n;++i){expected[i]=0;for(std::size_t j=1;j<n;++j)if(multiple?j%i==0:i%j==0)expected[i]+=a[j]*(inverse?mu(multiple?j/i:i/j):1);}
   if(multiple){if(inverse)multiple_mobius_transform(actual,sieve);else multiple_zeta_transform(actual,sieve);}else{if(inverse)divisor_mobius_transform(actual,sieve);else divisor_zeta_transform(actual,sieve);}require(actual==expected);
  }
  for(bool gcd:{false,true}){std::vector<std::int64_t>expected(n),self(n);for(std::size_t i=0;i<n;++i)for(std::size_t j=0;j<n;++j){auto k=gcd?std::gcd(i,j):std::lcm(i,j);if(k<n){expected[k]+=a[i]*b[j];self[k]+=a[i]*a[j];}}require((gcd?gcd_convolution(a,b,sieve):lcm_convolution(a,b,sieve))==expected);require((gcd?gcd_square(a,sieve):lcm_square(a,sieve))==self);}
 }
 std::vector<std::pair<int,std::int64_t>> f{{12,7},{6,-2},{4,3},{3,-4},{2,5},{1,1}};auto sorted=f;std::sort(sorted.begin(),sorted.end());auto expected=sorted;
 for(std::size_t i=0;i<sorted.size();++i){expected[i].second=0;for(auto[k,v]:sorted)if(k%sorted[i].first==0)expected[i].second+=v;}
 sparse_multiple_zeta_transform(f,sieve);require(f==expected);sparse_multiple_mobius_transform(f,sieve);require(f==sorted);
 auto mob=sieve.mobius_table(),phi=sieve.totient_table();for(int n=1;n<=128;++n){require(mob[n]==mu(n));int want=0;for(int j=1;j<=n;++j)want+=std::gcd(n,j)==1;require(phi[n]==want);}
}
void set_suite(){
 for(std::size_t n:{0U,1U,2U,8U,16U,32U,64U,128U,1024U}){
  std::vector<std::int64_t>a(n);for(std::size_t i=0;i<n;++i)a[i]=static_cast<int>(i%9)-4;
  for(bool subset:{false,true})for(bool inverse:{false,true}){std::vector<std::int64_t>expected(n);for(std::size_t i=0;i<n;++i)for(std::size_t j=0;j<n;++j)if(subset?(i&j)==j:(i&j)==i){const auto coefficient=inverse&&(std::popcount(i^j)&1)?-1:1;expected[i]+=coefficient*a[j];}auto actual=a;if(subset){if(inverse)subset_mobius_transform(actual);else subset_zeta_transform(actual);}else{if(inverse)superset_mobius_transform(actual);else superset_zeta_transform(actual);}require(actual==expected);}
 }
 std::vector<std::int64_t>a(32),b(32);for(std::size_t i=0;i<32;++i){a[i]=static_cast<int>(i%7)-3;b[i]=static_cast<int>(i%5)-2;}for(bool is_and:{false,true}){std::vector<std::int64_t>expected(32),self(32);for(std::size_t i=0;i<32;++i)for(std::size_t j=0;j<32;++j){const auto k=is_and?(i&j):(i|j);expected[k]+=a[i]*b[j];self[k]+=a[i]*a[j];}require((is_and?bitwise_and_convolution(a,b):bitwise_or_convolution(a,b))==expected);require((is_and?bitwise_and_square(a):bitwise_or_square(a))==self);}
}
void algorithm_suite(){
 std::vector<std::int64_t>a(129);for(std::size_t i=0;i<a.size();++i)a[i]=static_cast<std::int64_t>((i*7919)%197)-98;a[1]=std::numeric_limits<std::int64_t>::min();a[127]=std::numeric_limits<std::int64_t>::max();auto sorted=a;std::stable_sort(sorted.begin(),sorted.end());auto actual=a;RadixSort(actual);require(actual==sorted);auto order=RadixSortOrder(a);for(std::size_t i=0;i<order.size();++i){require(a[order[i]]==sorted[i]);if(i&&a[order[i-1]]==a[order[i]])require(order[i-1]<order[i]);}
 std::vector<std::uint8_t>masks;for_each_combination<std::uint8_t>(8,3,[&](auto mask){masks.push_back(mask);});std::vector<std::uint8_t>expected;for(unsigned mask=0;mask<256;++mask)if(std::popcount(mask)==3)expected.push_back(static_cast<std::uint8_t>(mask));require(masks==expected);require(last_combination<std::uint8_t>(8,3)==224);
 Heap heap({4,-7,0,4,9,-1});std::vector<int>vals{-7,-1,0,4,4,9};for(int v:vals)require(heap.pop_value()==v);require(heap.empty());
 Trie trie;std::vector<std::string>words{"","ab","abc","abc",std::string("\xff",1),std::string("\0a",2)};for(auto&w:words)trie.insert(w);require(trie.size()==words.size());require(trie.count("abc")==2);require(trie.prefix_count("a")==3);require(trie.erase("abc"));require(trie.count("abc")==1);require(trie.count(std::string("\0a",2))==1);require(trie.kth(0)==std::string{});
 std::vector<std::vector<std::int32_t>>matrix(32,std::vector<std::int32_t>(33));for(int i=0;i<32;++i)for(int j=0;j<33;++j)matrix[i][j]=i*100+j;auto rotated=rotate_90r(matrix);require(rotated.size()==33);for(int i=0;i<33;++i)for(int j=0;j<32;++j)require(rotated[i][j]==matrix[31-j][i]);require(rotate_90l(rotated)==matrix);require(transpose(transpose(matrix))==matrix);
}
}
int main(){integer_suite();set_suite();algorithm_suite();std::cout<<"PASS combined zeta/math/algorithms checks="<<checks<<'\n';}

