messages=['RadixSort: value exceeds maximum','PrimeBinomial: prime modulus required','PrimeBinomial: modulus changed','ModIntBinomial: modulus changed','superset_zeta_transform: length must be a power of two','integer transform: sieve too small','integer convolution: different lengths','sparse integer transform: duplicate key','IntegerSieve: negative table limit']
for mode,cc in [('gcc',['g++']),('clang',['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0'])]:
 for skip in [False,True]:
